import re

def parse(lines):
    blocks = {}
    order = []
    skip = []
    def add(name, kind, i, rec):
        if name not in blocks:
            blocks[name] = {'name': name, 'kind': kind, 'lines': [], 'records': []}
            order.append(name)
        b = blocks[name]
        b['lines'].append(i)
        if kind == 'kv':
            if not b['records']:
                b['records'].append({})
            b['records'][0].update(rec)
        else:
            b['records'].append(rec)
    SZ = '[\\d.]+ (?:bytes|[KMGT]B)'
    def P(n):
        return '\\(\\s*(?P<' + n + '>[<>]?\\d+%)\\)'
    total_re = re.compile('^Total Usage - (?P<l>\\d+) loaders, (?P<c>\\d+) classes(?: \\((?P<s>\\d+) shared\\))?:\\s*$')
    usage_re = re.compile('^\\s*(?P<t>[\\w-]+):\\s+(?P<ch>\\d+) chunks,\\s+(?P<cap>' + SZ + ') capacity,\\s+(?P<com>' + SZ + ') ' + P('comp') + ' committed,\\s+(?P<used>' + SZ + ') ' + P('usedp') + ' used,\\s+(?P<free>' + SZ + ') ' + P('freep') + ' free,\\s+(?P<waste>' + SZ + ') ' + P('wastep') + ' waste\\s*(?:,\\s*deallocated: (?P<db>\\d+) blocks with (?P<ds>' + SZ + '))?\\s*$')
    virt_re = re.compile('^\\s*(?P<s>\\S(?:.*?\\S)?):\\s+(?P<res>' + SZ + ') reserved,\\s+(?P<com>' + SZ + ') ' + P('comp') + ' committed(?:,\\s+(?P<n>\\d+) nodes)?\\.?\\s*$')
    fl_title = re.compile('^\\s*(?P<t>[\\w-]+):\\s*$')
    fl_row = re.compile('^\\s*(?P<sz>\\d+[kmg]):\\s+(?:\\(none\\)|(?P<n>\\d+), capacity=(?P<cap>' + SZ + '), committed=(?P<com>' + SZ + ') ' + P('comp') + ')\\s*$')
    fl_tot = re.compile('^\\s*Total word size: (?P<ws>' + SZ + '), committed: (?P<com>' + SZ + ') ' + P('comp') + '\\s*$')
    waste_re = re.compile('^\\s*(?P<k>\\S(?:.*?\\S)?):\\s+(?P<sz>' + SZ + ') ' + P('p') + '(?:\\s+\\((?P<b>\\d+) blocks\\))?\\s*$')
    pool_re = re.compile('^chunk header pool: (?P<n>\\d+) items, (?P<sz>' + SZ + ')\\.?\\s*$')
    kv_re = re.compile('^(?:\\s*- )?(?P<k>[^:]+?):\\s*(?P<v>.*?)\\.?\\s*$')
    sec = None
    fl = ''
    for i, line in enumerate(lines):
        s = line.strip()
        if not s:
            continue
        m = total_re.match(line)
        if m:
            sec = 'usage'
            add('total_usage', 'kv', i, {'loaders': m.group('l'), 'classes': m.group('c'), 'shared': m.group('s') or ''})
            continue
        if re.match('^\\d+:\\s*$', line):
            skip.append(i); continue
        if s == 'Virtual space:':
            sec = 'virt'; skip.append(i); continue
        if s == 'Chunk freelists:':
            sec = 'fl'; skip.append(i); continue
        if line.startswith('Waste'):
            sec = 'waste'; skip.append(i); continue
        if s == 'Internal statistics:':
            sec = 'stats'; skip.append(i); continue
        if s == 'Settings:':
            sec = 'settings'; skip.append(i); continue
        m = pool_re.match(line)
        if m:
            add('chunk_header_pool', 'kv', i, {'items': m.group('n'), 'size': m.group('sz')})
            continue
        if sec == 'usage':
            m = usage_re.match(line)
            if m:
                add('usage', 'table', i, {'type': m.group('t'), 'chunks': m.group('ch'), 'capacity': m.group('cap'), 'committed': m.group('com'), 'committed %': m.group('comp'), 'used': m.group('used'), 'used %': m.group('usedp'), 'free': m.group('free'), 'free %': m.group('freep'), 'waste': m.group('waste'), 'waste %': m.group('wastep'), 'deallocated blocks': m.group('db') or '', 'deallocated': m.group('ds') or ''})
                continue
        elif sec == 'virt':
            m = virt_re.match(line)
            if m:
                add('virtual_space', 'table', i, {'space': m.group('s'), 'reserved': m.group('res'), 'committed': m.group('com'), 'committed %': m.group('comp'), 'nodes': m.group('n') or ''})
                continue
        elif sec == 'fl':
            m = fl_row.match(line)
            if m:
                add('chunk_freelists', 'table', i, {'list': fl, 'chunk size': m.group('sz'), 'count': m.group('n') or '0', 'capacity': m.group('cap') or '', 'committed': m.group('com') or '', 'committed %': m.group('comp') or ''})
                continue
            m = fl_tot.match(line)
            if m:
                add('chunk_freelist_totals', 'table', i, {'list': fl, 'total word size': m.group('ws'), 'committed': m.group('com'), 'committed %': m.group('comp')})
                continue
            m = fl_title.match(line)
            if m:
                fl = m.group('t'); skip.append(i); continue
        elif sec == 'waste':
            m = waste_re.match(line)
            if m:
                add('waste', 'table', i, {'item': m.group('k'), 'size': m.group('sz'), 'percent': m.group('p'), 'blocks': m.group('b') or ''})
                continue
        elif sec in ('stats', 'settings'):
            m = kv_re.match(line)
            if m:
                add('internal_statistics' if sec == 'stats' else 'settings', 'kv', i, {m.group('k').strip(): m.group('v')})
                continue
    return {'blocks': [blocks[n] for n in order], 'skip': skip}
